import React from "react"
import "./BannerArea.css"

const Result = (props) => {
    const {professor, onChangeProfessor} = props;
    const endpoint = professor.endpoint ? professor.endpoint : null;
    if(endpoint != null){
        return (
            <>
                <div className={"result"} onClick={() => onChangeProfessor(professor)}>
                    {professor.name}
                </div>
            </>
        )
    }
};

export default Result;
